    --white:#FBFAF7;
    --grey:#D8D6D0;
    --line:clamp(8px, 1.1vw, 14px); /* the thick black lines */
    --font:"Archivo", "Helvetica Neue", Arial, sans-serif;
  }
  *{ margin:0; padding:0; box-sizing:border-box; }
  html{ scroll-behavior:smooth; }
  body{
    background:var(--black);
    color:var(--black);
    font-family:var(--font);
    font-size:17px;
    line-height:1.55;
  }
  ::selection{ background:var(--yellow); color:var(--black); }
  a{ color:inherit; }
  :focus-visible{ outline:4px solid var(--blue); outline-offset:3px; }

  /* The whole page is one composition: white cells separated by black lines. */
  .composition{
    display:grid;
    gap:var(--line);
    padding:var(--line);
    max-width:1440px;
    margin:0 auto;
  }
  .cell{ background:var(--white); position:relative; overflow:hidden; }

