  .hero-title .byline{ margin-top:1.1em; font-weight:700; font-size:clamp(1rem, 1.4vw, 1.2rem); }
  .hero-title .byline span{ display:block; font-weight:400; }

  .block{ border:0; cursor:default; }
  .block .tag{
    position:absolute; left:0; bottom:0;
    background:var(--black); color:var(--white);
    font-size:0.85rem; font-weight:500; letter-spacing:0.02em;
    padding:0.5em 0.9em;
    opacity:0; transform:translateY(100%);
    transition:opacity .25s ease, transform .25s ease;
    pointer-events:none;
    max-width:100%;
  }
  .block:hover .tag, .block:focus-visible .tag{ opacity:1; transform:translateY(0); }
